function spaceKeyWords(name){return String(name||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().match(/[A-Z0-9]+/g)||[]}
function uniqueSpaceKey(base,excludedKey=''){let key=base;while(PROJECTS[key]&&key!==excludedKey)key+='*';return key}
function sharedSpaceKey(name,excludedKey=''){const words=spaceKeyWords(name),base=words.length<=1?(words[0]||'SPC').slice(0,3):words.length===2?`${words[0][0]||''}${words[1].slice(0,2)}`:words.slice(0,3).map(word=>word[0]||'').join('');return uniqueSpaceKey(base.padEnd(3,'X'),excludedKey)}
function userSpaceKey(fullName){const words=spaceKeyWords(fullName),base=`${words[0]?.[0]||'U'}${words.at(-1)?.[0]||'S'}*`;let key=base;while(PROJECTS[key])key=`*${key}`;return key}
const PERSONAL_KEY_MIGRATION={};
function normalizePersonalSpaceKeys(){
  const entries=Object.entries(PERSONAL_SPACE_OWNERS),occupied=new Set(Object.keys(PROJECTS).filter(key=>!PERSONAL_SPACE_OWNERS[key])),normalized=[];
  for(const [oldKey,owner] of entries){const words=spaceKeyWords(owner),base=`${words[0]?.[0]||'U'}${words.at(-1)?.[0]||'S'}*`;let newKey=base;while(occupied.has(newKey))newKey=`*${newKey}`;occupied.add(newKey);normalized.push([oldKey,newKey,owner,PROJECTS[oldKey]||{name:`${owner}'s Space`,color:'#617a9d'}]);if(oldKey!==newKey)PERSONAL_KEY_MIGRATION[oldKey]=newKey}
  for(const [oldKey] of entries){delete PERSONAL_SPACE_OWNERS[oldKey];delete PROJECTS[oldKey]}
  for(const [,newKey,owner,project] of normalized){PERSONAL_SPACE_OWNERS[newKey]=owner;PROJECTS[newKey]={...project,name:`${owner}'s Space`}}
}
normalizePersonalSpaceKeys();
