function migratedSharedTask(task){if(!task)return task;const migrated={...task};if(migrated.project==='LEG')migrated.project='LCO';if(String(migrated.id||'').startsWith('LEG-'))migrated.id=`LCO-${String(migrated.id).slice(4)}`;if(String(migrated.parent||'').startsWith('LEG-'))migrated.parent=`LCO-${String(migrated.parent).slice(4)}`;return migrated}
