  if(state.supervisedFirst)mainRows=[...mainRows].sort((a,b)=>Number(taskSupervisor(state.tasks.find(task=>task.id===b.id))===CURRENT_USER)-Number(taskSupervisor(state.tasks.find(task=>task.id===a.id))===CURRENT_USER));
