function openTask(id,preserveDirty=false){const t=state.tasks.find(x=>x.id===id);if(!canAppearInMainFilter(t)){toast('You do not have access to this task');return}if(!preserveDirty||taskDetailsDraft?.id!==id){taskDetailsDirtyId=null;taskDetailsDraft={id:t.id,title:t.title,description:t.description||'',assignee:t.assignee||'Unassigned',supervisor:taskSupervisor(t)||'Unassigned',approver:taskApprover(t)||DEFAULT_APPROVER,project:t.project,priority:t.priority||'Medium',dueDate:t.dueDate||null,targetStartDate:t.targetStartDate||null,unblockingDate:t.unblockingDate||null,disableMainAdminReminders:Boolean(t.disableMainAdminReminders),lastHumanActivityAt:t.lastHumanActivityAt||t.created,labels:[...(t.labels||[])],comments:(t.comments||[]).map(comment=>({...comment,images:[...(comment.images||[])]})),status:t.status,statusReason:t.cancellationReason||t.blockedReason||''}}const d=taskDetailsDraft,assigneeControl=canManageAssignments(t)?`<select class="detail-select" onchange="changeTaskAssigneeFromDetails('${t.id}',this.value)"><option value="Unassigned" ${d.assignee==='Unassigned'?'selected':''}>Unassigned</option>${personOptions(d.assignee)}</select>`:`<strong>${esc(d.assignee||'Unassigned')}</strong>`;document.getElementById('modalContent').innerHTML=`<p class="eyebrow">${d.project} / ${t.id}${t.isMiniTask?' / MINI TASK':''}</p><h2 id="modalTitle" class="editable-task-title" ${taskDetailEditableAttributes(t,"title")}>${esc(d.title)}</h2><p class="modal-sub">${t.isMiniTask?'Mini Task':'Task'} details</p><div class="detail-grid"><div class="detail-item"><span>Status</span>${taskDetailStatusControl(t)}</div><div class="detail-item"><span>Assignee</span>${assigneeControl}</div><div class="detail-item"><span>Supervisor</span>${taskDetailSupervisorControl(t)}</div><div class="detail-item"><span>Approver</span>${taskDetailApproverControl(t)}</div><div class="detail-item"><span>Space</span>${taskDetailSpaceControl(t)}</div><div class="detail-item"><span>Priority</span>${taskDetailPriorityControl(t)}</div><div class="detail-item"><span>Due Date</span>${taskDetailDueDateControl(t)}</div><div class="detail-item"><span>Target Start Date</span>${taskDetailTargetStartDateControl(t)}</div><div class="detail-item"><span>Unblocking Date</span>${taskDetailUnblockingDateControl(t)}</div><div class="detail-item detail-labels-item"><span>Labels</span>${taskDetailLabelsControl(t)}</div>${taskDetailReminderControl(t)}</div><p class="description editable-task-description" ${taskDetailEditableAttributes(t,"description")}>${esc(d.description)}</p>${d.status==='cancelled'?`<section class="status-reason-panel cancelled-reason"><span>Cancellation reason</span><p>${esc(d.statusReason||'Pending submission')}</p></section>`:''}<div class="modal-actions"><button class="action-btn" data-task-id="${t.id}" onclick="openSubtaskModal(this.dataset.taskId)">+ Create subtask</button>${isMainAdmin()?`<button class="action-btn danger" data-task-id="${t.id}" onclick="deleteTaskFromContext(this.dataset.taskId)">Delete task</button>`:String()}</div>${!canEditTaskFields(t)?`<p class="permission-hint">🔒 The Supervisor has standard user permissions. The Assignee can use the defined workflow, while the Approver or an Administrator can fully manage this task.</p>`:''}<div class="audit"><h4>Activity history</h4>${t.audit.map(a=>`<div class="audit-entry"><strong>${esc(a)}</strong><br>Today</div>`).join('')}</div>${taskViewersTable(t)}${commentSection(t)}`;const footer=document.getElementById('taskDetailsFooter');footer.innerHTML=taskSubmitButton(t);footer.classList.remove('hidden');showModal(true)}
function commentSection(task){const comments=taskDetailsDraft?.id===task.id?(taskDetailsDraft.comments||[]):(task.comments||[]),canDelete=isMainAdmin();return `<section class="comments"><h4>Comments <span>${comments.length}</span></h4><form class="comment-form" onsubmit="addComment('${task.id}',event)"><textarea id="commentInput-${task.id}" name="comment" placeholder="Write a comment… Use @ to mention a user" oninput="handleCommentMention(this,'${task.id}')" onkeydown="handleCommentMentionKeydown(this,'${task.id}',event)" onblur="setTimeout(()=>closeCommentMention('${task.id}'),150)"></textarea><div id="commentMention-${task.id}" class="comment-mention-menu"></div><div id="commentPreview-${task.id}" class="comment-preview"></div><div class="comment-tools"><label class="photo-upload">📷 Add photos<input name="photos" type="file" accept="image/*" multiple onchange="previewCommentImages(this,'${task.id}')"></label><small>Up to 4 images</small><button type="submit">Add comment</button></div></form><div class="comment-list">${comments.length?comments.map(comment=>`<article class="comment ${comment.pending?'pending-comment':''}"><div class="comment-meta"><span class="mini-avatar">${initials(comment.author||CURRENT_USER)}</span><strong>${esc(comment.author||CURRENT_USER)}</strong><time>${comment.pending?'Pending submission':formatDateTime(comment.createdAt)}</time>${canDelete?`<button type="button" class="delete-comment-btn" data-task-id="${esc(task.id)}" data-comment-id="${esc(comment.id)}" onclick="deleteComment(this.dataset.taskId,this.dataset.commentId)">Delete</button>`:''}</div>${comment.text?`<p>${esc(comment.text)}</p>`:''}${comment.images?.length?`<div class="comment-images">${comment.images.map(src=>`<a href="${src}" target="_blank" title="Open image"><img src="${src}" alt="Comment attachment"></a>`).join('')}</div>`:''}</article>`).join(''):'<p class="no-comments">No comments yet.</p>'}</div></section>`}
function handleCommentMention(textarea,taskId){const before=textarea.value.slice(0,textarea.selectionStart),at=before.lastIndexOf('@'),menu=document.getElementById(`commentMention-${taskId}`);if(!menu)return;if(at<0||/\n/.test(before.slice(at))){menu.innerHTML='';return}const query=before.slice(at+1).trim().toLowerCase(),matches=PEOPLE.filter(person=>!query||person.name.toLowerCase().includes(query));if(!matches.length){menu.innerHTML='';return}textarea.dataset.mentionStart=String(at);menu.innerHTML=matches.map((person,index)=>`<button type="button" class="${index===0?'mention-active':''}" onmousedown="event.preventDefault();insertCommentMention('${taskId}','${esc(person.name)}')"><i>${person.initials}</i><span>${esc(person.name)}</span></button>`).join('');requestAnimationFrame(adjustDropdownDirections)}
function handleCommentMentionKeydown(textarea,taskId,event){const menu=document.getElementById(`commentMention-${taskId}`),buttons=[...(menu?.querySelectorAll('button')||[])];if(!buttons.length)return;if(event.key==='Escape'){event.preventDefault();closeCommentMention(taskId);return}if(!['ArrowDown','ArrowUp','Enter'].includes(event.key))return;event.preventDefault();const current=Math.max(0,buttons.findIndex(button=>button.classList.contains('mention-active')));if(event.key==='Enter'){const selected=buttons[current];insertCommentMention(taskId,selected.querySelector('span').textContent);return}buttons[current].classList.remove('mention-active');const next=event.key==='ArrowDown'?(current+1)%buttons.length:(current-1+buttons.length)%buttons.length;buttons[next].classList.add('mention-active');buttons[next].scrollIntoView({block:'nearest'})}
function insertCommentMention(taskId,name){const textarea=document.getElementById(`commentInput-${taskId}`);if(!textarea)return;const caret=textarea.selectionStart,at=Number(textarea.dataset.mentionStart??textarea.value.lastIndexOf('@',caret)),before=textarea.value.slice(0,at),after=textarea.value.slice(caret);textarea.value=`${before}@${name} ${after}`;const next=before.length+name.length+2;textarea.setSelectionRange(next,next);textarea.focus();closeCommentMention(taskId)}
function closeCommentMention(taskId){const menu=document.getElementById(`commentMention-${taskId}`);if(menu)menu.innerHTML=''}
function previewCommentImages(input,id){const preview=document.getElementById(`commentPreview-${id}`),files=[...input.files].slice(0,4);preview.innerHTML='';for(const file of files){if(!file.type.startsWith('image/'))continue;const reader=new FileReader();reader.onload=()=>preview.insertAdjacentHTML('beforeend',`<img src="${reader.result}" alt="Selected image">`);reader.readAsDataURL(file)}if(input.files.length>4)toast('You can attach up to 4 images')}
function compressCommentImage(file){return new Promise((resolve,reject)=>{if(!file.type.startsWith('image/')){reject(new Error('Only image files are allowed'));return}if(file.size>10*1024*1024){reject(new Error('Each image must be smaller than 10 MB'));return}const reader=new FileReader();reader.onerror=()=>reject(new Error('The image could not be read'));reader.onload=()=>{const image=new Image();image.onerror=()=>reject(new Error('The image could not be processed'));image.onload=()=>{const scale=Math.min(1,1600/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.78))};image.src=reader.result};reader.readAsDataURL(file)})}
async function addComment(id,event){event.preventDefault();const form=event.currentTarget,textValue=form.elements.comment.value.trim(),files=[...form.elements.photos.files].slice(0,4);if(!textValue&&!files.length){toast('Write a comment or attach a photo');return}const button=form.querySelector('button[type="submit"]');button.disabled=true;button.textContent='Adding…';try{const images=await Promise.all(files.map(compressCommentImage));if(taskDetailsDraft?.id!==id)throw new Error('The task editor is no longer open');const createdAt=new Date().toISOString(),comment={id:`comment-${Date.now()}`,author:CURRENT_USER,role:roleName(),text:textValue,images,createdAt,pending:true,human:true};taskDetailsDraft.comments=taskDetailsDraft.comments||[];taskDetailsDraft.comments.unshift(comment);taskDetailsDraft.lastHumanActivityAt=createdAt;markTaskDetailsDirty(id);openTask(id,true);toast('Comment added. Press Submit to save it.')}catch(error){button.disabled=false;button.textContent='Add comment';toast(error.message||'The comment could not be added')}}
function mentionedPeopleInComment(text){
  const content=String(text||'');
  return PEOPLE
    .filter(person=>person.name!==CURRENT_USER)
    .filter(person=>{
      const escaped=person.name.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
      return new RegExp(`(^|\\s)@${escaped}(?=\\s|[.,!?;:]|$)`,'i').test(content);
    })
    .map(person=>person.name);
}
async function invokeNotificationWithRetry(payload,attempts=3){
  let lastError;
  for(let attempt=1;attempt<=attempts;attempt+=1){
    try{return await window.shgInvokeFunction('send-mention-email',payload)}
    catch(error){
      lastError=error;
      if(attempt<attempts)await new Promise(resolve=>setTimeout(resolve,attempt*900));
    }
  }
  throw lastError;
}
function sendMentionEmails(task,comment){
  if(comment.system||comment.automationType||typeof window.shgInvokeFunction!=='function')return;
  const explicitlyMentioned=mentionedPeopleInComment(comment.text),recipientRoles={};
  for(const name of explicitlyMentioned)recipientRoles[name]=[...(recipientRoles[name]||[]),'Mention'];
  if(task.assignee&&task.assignee!=='Unassigned')recipientRoles[task.assignee]=[...(recipientRoles[task.assignee]||[]),'Assignee'];
  const supervisor=taskSupervisor(task);if(supervisor&&supervisor!=='Unassigned')recipientRoles[supervisor]=[...(recipientRoles[supervisor]||[]),'Supervisor'];
  const mentionedNames=[...new Set(Object.keys(recipientRoles).filter(name=>name!==CURRENT_USER))];
  if(!mentionedNames.length)return;
  invokeNotificationWithRetry({
    notificationType:'comment',
    taskKey:task.id,
    taskTitle:task.title,
    comment:String(comment.text||''),
    commentId:String(comment.id||''),
    authorName:CURRENT_USER,
    mentionedNames,
    recipientRoles,
  }).then(result=>{
    if(result.sent>0)toast(`${result.sent} mention email${result.sent===1?'':'s'} sent`);
    const waiting=Math.max(0,(result.queued||0)-(result.sent||0));
    if(waiting>0)toast(`${waiting} mention email${waiting===1?' is':'s are'} safely queued`);
    if(result.failed>0)toast(`${result.failed} mention notification${result.failed===1?'':'s'} could not be delivered after all retries`);
  }).catch(error=>{
    console.error('Mention notification failed',error);
    toast('Comment saved, but the mention email could not be sent');
  });
}
function sendAssigneeChangedEmail(task,previousAssignee,changedAt){
  if(typeof window.shgInvokeFunction!=='function'||!task.assignee||task.assignee==='Unassigned'||task.assignee===CURRENT_USER)return;
  const comment=`${CURRENT_USER} changed the Assignee from ${previousAssignee||'Unassigned'} to ${task.assignee}. You are now the Assignee of this task.`;
  invokeNotificationWithRetry({
    notificationType:'comment',
    taskKey:task.id,
    taskTitle:task.title,
    comment,
    commentId:`assignee-change:${task.id}:${changedAt}`,
    authorName:CURRENT_USER,
    mentionedNames:[task.assignee],
    recipientRoles:{[task.assignee]:['Assignee']},
  }).then(result=>{
    if(result.sent>0)toast(`Assignment email sent to ${task.assignee}`);
    const waiting=Math.max(0,(result.queued||0)-(result.sent||0));
    if(waiting>0)toast(`Assignment email for ${task.assignee} is safely queued`);
  }).catch(error=>{
    console.error('Assignee change notification failed',error);
    toast(`The Assignee changed, but the email to ${task.assignee} could not be sent`);
  });
}
function sendTaskCreatedEmails(task){
  if(typeof window.shgInvokeFunction!=='function')return;
  const recipientRoles={};
  for(const [name,role] of [[task.assignee,'Assignee'],[task.supervisor,'Supervisor'],[task.approver,'Approver']])if(name&&name!=='Unassigned')recipientRoles[name]=[...(recipientRoles[name]||[]),role];
  const recipientNames=[...new Set(Object.keys(recipientRoles).filter(name=>name!==CURRENT_USER))];
  if(!recipientNames.length)return;
  invokeNotificationWithRetry({
    notificationType:'task_created',
    taskKey:task.id,
    taskTitle:task.title,
    authorName:CURRENT_USER,
    mentionedNames:recipientNames,
    recipientRoles,
  }).then(result=>{
    if(result.sent>0)toast(`${result.sent} task assignment email${result.sent===1?'':'s'} sent`);
    const waiting=Math.max(0,(result.queued||0)-(result.sent||0));
    if(waiting>0)toast(`${waiting} task assignment email${waiting===1?' is':'s are'} safely queued`);
  }).catch(error=>{
    console.error('Task creation notification failed',error);
    toast('Task saved, but its assignment email could not be sent');
  });
}
function deleteComment(taskId,commentId){
  const task=state.tasks.find(item=>item.id===taskId);
  if(!isMainAdmin()){toast('Only the Main Admin can delete comments');return}
  if(taskDetailsDraft?.id!==taskId)return;
  const index=(taskDetailsDraft.comments||[]).findIndex(comment=>String(comment.id)===String(commentId));
  if(!task||index<0){toast('Comment not found');return}
  const comment=taskDetailsDraft.comments[index];
  if(!confirm(`Delete this comment by ${comment.author||'Unknown user'}?`))return;
  taskDetailsDraft.comments.splice(index,1);
  markTaskDetailsDirty(taskId);
  openTask(taskId,true);
  toast('Comment removed. Press Submit to save the change.')
}
