function openStatusReasonModal(id,target){const task=state.tasks.find(item=>item.id===id);if(!task||!canTransition(task,target)){toast(transitionPermission(task,target));return}const label=target==='blocked'?'Block task':'Cancel task',placeholder=target==='blocked'?'Explain what is blocking this task…':'Explain why this task is being cancelled…';document.getElementById('modalContent').innerHTML=`<p class="eyebrow">${task.id} / STATUS</p><h2 id="modalTitle">${label}</h2><p class="modal-sub">A reason is required for this status change.</p><form id="statusReasonForm" class="task-form"><div class="field"><label>Reason</label><textarea name="reason" required autofocus placeholder="${placeholder}"></textarea></div><div class="form-row"><button type="button" class="action-btn" onclick="openTask('${task.id}')">Cancel</button><button type="submit" class="primary-btn">Confirm ${target==='blocked'?'Blocked':'Cancelled'}</button></div></form>`;showModal();document.getElementById('statusReasonForm').onsubmit=event=>{event.preventDefault();const reason=new FormData(event.target).get('reason').trim();if(!reason){toast('A reason is required');return}moveTask(id,target,reason)}}
function moveTask(id,target,reason=null){const t=state.tasks.find(x=>x.id===id);if(!canTransition(t,target)){toast(transitionPermission(t,target));return}if(['blocked','cancelled'].includes(target)&&reason===null){openStatusReasonModal(id,target);return}const reasonText=String(reason||'').trim();if(['blocked','cancelled'].includes(target)&&!reasonText){toast('A reason is required');return}const fromStatus=t.status,from=STATUSES.find(s=>s.id===fromStatus).label,to=STATUSES.find(s=>s.id===target).label,changedAt=new Date().toISOString();t.status=target;t.jiraStatus=to;t.updated=changedAt;t.lastStatusChangedAt=changedAt;if(target==='cancelled')t.cancellationReason=reasonText;if(isTaskAssignee(t)&&state.role!=='admin'&&fromStatus==='todo'&&target==='progress'){t.progressLog=t.progressLog||[];t.progressLog.unshift({assignee:t.assignee,at:changedAt})}mentionApproverForUserStatusChange(t,fromStatus,target,changedAt);addStatusChangeComment(t,fromStatus,target,changedAt);t.audit.unshift(`${from} → ${to} by ${roleName()}${reasonText?`: ${reasonText}`:''}`);save();closeModal();render();toast(`Task moved to ${to}`)}
function openSpaceAccessModal(projectKey){if(state.role!=='admin'){toast('Only an Administrator can manage Space access');return}const project=PROJECTS[projectKey],allowed=new Set(state.spaceAccess[projectKey]||[]),allSelected=PEOPLE.every(person=>allowed.has(person.name));document.getElementById('modalContent').innerHTML=`<p class="eyebrow">SPACE ACCESS</p><h2 id="modalTitle">${esc(project.name)}</h2><p class="modal-sub">Choose which users can view and access this Space.</p><form id="spaceAccessForm" class="space-access-form"><label class="space-access-all"><input type="checkbox" ${allSelected?'checked':''} onchange="toggleAllSpaceUsers(this.checked)"><strong>Select All</strong></label><div class="space-user-list">${PEOPLE.map(person=>`<label><input type="checkbox" name="spaceUser" value="${esc(person.name)}" ${allowed.has(person.name)?'checked':''}><span class="table-person"><i>${person.initials}</i>${esc(person.name)}</span></label>`).join('')}</div><p class="access-note">Administrators always retain full access to every Space.</p><button class="primary-btn space-access-apply" type="submit">Apply</button></form>`;showModal();document.getElementById('spaceAccessForm').onsubmit=event=>{event.preventDefault();state.spaceAccess[projectKey]=[...event.currentTarget.querySelectorAll('input[name="spaceUser"]:checked')].map(input=>input.value);saveSpaceAccess();closeModal();render();toast(`Access updated for ${project.name}`)}}
