function taskCreationLabelControl(){const labels=columnValues('labels').sort((a,b)=>a.localeCompare(b,'en',{sensitivity:'base'})),createOption=state.role==='admin'?'<option value="__create_new_label__">+ Create new label</option>':'';return `<select name="label" onchange="handleCreationLabelChoice(this)"><option value="">No label</option>${labels.map(label=>`<option value="${esc(label)}">${esc(label)}</option>`).join('')}${createOption}</select>`}
