function openTaskTextEditor(id){const task=state.tasks.find(item=>item.id===id);if(!task||!canEditTaskFields(task)){toast('Only the task Approver or an Administrator can edit the text');return}document.getElementById('modalContent').innerHTML=`<p class="eyebrow">EDIT TASK / ${task.id}</p><h2 id="modalTitle">Edit task text</h2><form id="taskTextForm" class="task-form"><div class="field"><label>Title</label><input name="title" maxlength="300" required value="${esc(task.title)}"></div><div class="field"><label>Description</label><textarea name="description" placeholder="Add a description…">${esc(task.description||'')}</textarea></div><div class="form-row"><button type="button" class="action-btn" onclick="openTask('${task.id}')">Cancel</button><button class="primary-btn" type="submit">Save changes</button></div></form>`;showModal();document.getElementById('taskTextForm').onsubmit=event=>{event.preventDefault();saveTaskText(task.id,new FormData(event.target).get('title'),new FormData(event.target).get('description'))}}
function saveTaskText(id,title,description){const task=state.tasks.find(item=>item.id===id);if(!task||!canEditTaskFields(task)){toast('Only the task Approver or an Administrator can edit the text');return}const cleanTitle=String(title||'').trim(),cleanDescription=String(description||'').trim();if(!cleanTitle){toast('The task title is required');return}const row=(window.VICTOR_MAIN_FILTER||[]).find(item=>item.id===id),changedAt=new Date().toISOString();task.title=cleanTitle;task.description=cleanDescription||'No description has been added.';task.updated=changedAt;task.audit.unshift(`Task text edited by ${CURRENT_USER}`);if(row){row.summary=cleanTitle;row.updated=changedAt}save();render();openTask(id);toast(`${id} text updated`)}
